-- Two-Players Thin Twins: the seated second brother holds seat 0 of the first brother's vehicle (seat 9600, hidden),
-- so the stand-in twin can only ride piggyback, in the saddle, on a beast's back or on the shoulders when the body
-- carries a copy of that twin vehicle with seat 0 added for him: twin vehicle N becomes N + 100, seat 1 unchanged.
-- AscensionCompat streams these rows to clients at login.

DELETE FROM `vehicle_dbc` WHERE `ID` IN (9630, 9631, 9632, 9633, 9634, 9635, 9636, 9637, 9638, 9639, 9640, 9641, 9642, 9643, 9644, 9645, 9646, 9647, 9648, 9649, 9650, 9651, 9652, 9698);
